const on = String(msg.payload) === '1';
msg.payload = on ? '<div style="background:#c0392b;color:#fff;padding:10px;border-radius:8px;text-align:center;font-weight:bold">E-STOP ACTIVE - all pumps and motors off</div>'
                 : '<div style="background:#27ae60;color:#fff;padding:10px;border-radius:8px;text-align:center">System armed</div>';
return msg;

const s = msg.payload || {};
const pretty = String(s.state || 'UNKNOWN');
return [{payload: pretty}, {payload: s.state_id}, {payload: s.battery_v}];

const t = msg.payload || {};
const cols = ['state','state_id','battery_v','s1','s2','s3','arm','transfer_ml','chlorine_ml','delivered_ml','health','estop'];
let line = new Date().toISOString() + ',' + cols.map(c => t[c] !== undefined ? (typeof t[c] === 'object' ? JSON.stringify(t[c]).replace(/,/g,';') : t[c]) : '').join(',');
if (!context.get('header')) { context.set('header', true); node.send({payload: 'time,' + cols.join(',')}); }
msg.payload = line;
return msg;

const t = msg.payload || {};
msg.payload = `${new Date().toLocaleTimeString()} - ${t.state || ''} - S1 ${t.s1 ?? '-'}% S3 ${t.s3 ?? '-'}% - delivered ${t.delivered_ml ?? 0} mL`;
return msg;

const s = msg.payload || {};
const fill = s.target_ml ? Math.min(100, 100 * (s.batch_ml || 0) / s.target_ml) : Number(s.level_pct || 0);
const flowTxt = s.flow_ml_s !== undefined ? ` . ${Number(s.flow_ml_s).toFixed(1)} mL/s . ${Number(s.batch_ml||0).toFixed(0)}/${Number(s.target_ml||0).toFixed(0)} mL` : '';
return [{payload: Math.round(fill)}, {payload: (s.pump ? 'PUMP ON' : 'pump off') + ' . ' + (s.state || '') + flowTxt + (s.fault ? ' . FAULT ' + s.fault : '')}];

const s = msg.payload || {};
return [{payload: `${Number(s.chlorine_total_ml||0).toFixed(2)} mL ${s.chlorine_on ? '(dosing)' : ''}`},
        {payload: Number(s.chlorine_stock_ml||0)}];

let a = Math.max(0, Math.min(90, Math.round(Number(msg.payload))));
if (!Number.isFinite(a)) return null;
msg.payload = 'ANGLE:' + a;
return msg;

const s = msg.payload || {};
msg.payload = s.inhibit ? 'INHIBITED (pumps / mission / e-stop)' : (s.left !== undefined ? `L ${s.left}  R ${s.right}` : `speed ${s.speed}`);
return msg;

const s = msg.payload || {};
msg.payload = s.phase ? `${s.auto === false ? 'MANUAL' : 'AUTO'} . ${s.phase} . next ${s.next || '-'}${s.leg_left !== undefined ? ' . ' + Number(s.leg_left).toFixed(2) + ' left' : ''}` : 'simulation (ground truth)';
return msg;

const s = msg.payload || {};
const names = ['Intake','Transfer','Chlorine','Delivery'];
const ch = (s.ch || []).map((on, i) => names[i] + (on ? ' ON' : ' off')).join(' . ');
return [{payload: Number(s.rail_v || 0)}, {payload: `${s.mode || '?'} . rail ${s.rail || '?'}${s.fault ? ' . ' + s.fault : ''}`}, {payload: ch}];
